package com.example.techfix;
import android.content.Intent; import android.os.*; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.example.techfix.data.AppDatabase; import com.example.techfix.data.entity.User; import com.example.techfix.data.repository.UserRepository; import java.util.concurrent.*;
public class LoginActivity extends AppCompatActivity {private final ExecutorService executor=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private UserRepository repo;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_login);repo=new UserRepository(AppDatabase.getDatabase(getApplicationContext()).userDao());EditText email=findViewById(R.id.etEmail),password=findViewById(R.id.etPassword);findViewById(R.id.btnLogin).setOnClickListener(v->{String e=email.getText().toString().trim(),p=password.getText().toString();if(e.isEmpty()||p.isEmpty()){Toast.makeText(this,"Please fill in all fields",Toast.LENGTH_SHORT).show();return;}executor.execute(()->{try{User u=repo.login(e,p);main.post(()->{Toast.makeText(this,"Welcome, "+u.getName()+"!",Toast.LENGTH_SHORT).show();Intent i=new Intent(this,HomeActivity.class);i.putExtra("USER_NAME",u.getName());i.putExtra("USER_ID",u.getUserId());startActivity(i);finish();});}catch(Exception ex){main.post(()->Toast.makeText(this,ex.getMessage(),Toast.LENGTH_SHORT).show());}});});findViewById(R.id.tvGoToRegister).setOnClickListener(v->startActivity(new Intent(this,RegisterActivity.class)));} @Override protected void onDestroy(){executor.shutdown();super.onDestroy();}}
